import json
T=json.load(open('/home/claude/jer/txt/31.json'))
def L(a,z):return '「'+''.join(T[a-1:z])+'」'
B=[
dict(a=1,z=3,star=3,lit=L(1,3),
key=[('神','H430','leloqim','神'),('子民','H5971','leam','子民'),('曠野','H4057','bamidbar','曠野'),('蒙恩','H2580','khen','恩寵'),('永遠','H5769','olam','永遠、久遠'),('慈愛','H2617','khesed','慈愛、信實的愛'),('吸引','H4900','meshaktikh','拉、吸引')],
gram=['**{H5769}**（olam，永遠）、**{H2617}**（khesed，慈愛）：「**我以永遠的愛愛你，因此我以慈愛吸引你**」。**這兩個字，一個說時間，一個說性質：愛是永遠的，愛是信實的。**','**{H4900}**（mashakh，拉）：「**吸引**」直譯是「**拉**」。**這個字，常用來形容用繩索把人拉過來。****神不是推著人走，而是用愛，把人拉回來。**','**{H7350}**（merakhoq，從遠處）：和合本譯作「**古時**」，原文直譯是「**從遠處**」，可以指時間遠，也可以指地方遠。**無論怎麼讀，神的愛，都是從很遠的地方就開始了。**'],
exp=['三十一章是**安慰之書的中心**。二十九章教人在被擄之地住下來，三十章說神必醫治破碎的民；現在，**神說出這一切的根源：一個永遠的愛。****這一章的第一個應許，就是二十二節同樣的一句話：「我必作以色列各家的神；他們必作我的子民。」**','二節說，**脫離刀劍的人，在曠野蒙恩。****曠野，是一個沒有東西的地方；可是經文說，那裡有「恩」。****人最缺乏的地方，常常正是神的恩典最顯明的地方。**','請留意三節的**次序**：**先是神的愛（永遠的愛），然後才是神的行動（吸引）。****神不是因為人回來，才開始愛；神是因為先愛，才把人拉回來。****這是整卷書最溫柔的一句話。**']),
dict(a=4,z=6,star=2,lit=L(4,6),
key=[('建立','H1129','evnekha','建造、建立'),('擊鼓','H8596','tupayikh','手鼓'),('跳舞','H4234','bamakhol','舞蹈'),('葡萄園','H3754','kramim','葡萄園'),('守望','H5341','notsrim','守望的人'),('錫安','H6726','tsiyon','錫安')],
gram=['**{H8596}**（tof，手鼓）：「**再以擊鼓為美**」。**手鼓，是歡慶的樂器。****米利暗在紅海邊拿著手鼓跳舞**（出十五20）。**神說，這樣的歌舞，要再回來。**','**{H5341}**（notsar，守望）：「**以法蓮山上守望的人**」。**守望的人，是那些站在高處、看見遠方的人。****這一次，他們看見的，不是敵人，而是歸回的路。**'],
exp=['神說：**「我要再建立你，你就被建立。」****這句話的語氣，是「我要」，結果是「就」。****重建，從神的行動開始。**請留意**「再」**字，出現了三次（四、五節）：**再建立、再以擊鼓、再栽種。****凡被毀壞的，神說，我要再來一次。**','**撒馬利亞的山上栽種葡萄園**：**撒馬利亞，是北國的首都，早已被亞述攻陷。****神的盼望，不只是南國，也包括早已消失的北國。****沒有一塊被遺忘的地方。**','六節**守望的人呼叫：「起來吧！我們可以上錫安，到耶和華我們的神那裡去。」****北國與南國，本來因為敬拜的地方而分裂；現在，他們一起上錫安。****這是一個共同敬拜的盼望。**']),
dict(a=7,z=9,star=3,lit=L(7,9),
key=[('歡樂歌唱','H7442','rnu','歡呼、歌唱'),('所剩下的人','H7611','sheerit','餘剩的人'),('北方','H6828','tsafon','北方'),('瞎子','H5787','iver','瞎眼的人'),('哭泣','H1065','bivekhi','哭泣'),('懇求','H8469','uvtakhanunim','求恩'),('長子','H1060','bekhori','我的長子')],
gram=['**{H8469}**（takhanun，求恩）：「**照他們懇求的**」，直譯是「**帶著求恩的聲音**」。**他們是帶著哭泣和求恩回來的。**神說，**我要照他們的求恩，引導他們。**','**{H1060}**（bekhor，長子）：「**以法蓮是我的長子**」。**以法蓮是約瑟的次子，卻被神稱為長子。****神的愛，不照出生的次序，而照祂的心意。**'],
exp=['七節是一聲歡呼，**卻出現在一群「所剩下的人」之中**。**不是勝利者的歡呼，而是倖存者的歌唱。**神說，**要為雅各歡樂歌唱。****歌唱，不是等到一切完全，而是在神開始作工的時候。**','八節的**名單，非常動人**：**瞎子、瘸子、孕婦、產婦。****是走得最慢的人，也是最需要照顧的人。****可是神說，他們必成為大幫回來。****神的歸回，不會丟下最軟弱的人。**','九節說：**他們要哭泣而來。****神不要求他們笑著回來；神接受哭泣的人。****祂要在河水旁，引導他們走正直的路，不致絆跌。****因為我是以色列的父。****歸回的力量，是一位父親的帶領。**']),
dict(a=10,z=12,star=2,lit=L(10,12),
key=[('牧人','H7462','kero','牧人'),('看守','H8104','ushmaro','看守'),('招聚','H6908','yqabtsenu','聚集'),('救贖','H6299','padah','贖回'),('園子','H1588','kegan','園子'),('愁煩','H1669','ledavah','憂愁、衰弱'),('五穀','H1715','dagan','五穀')],
gram=['**{H6299}**（padah，贖回）、**{H1350}**（ga’al，救贖）：**十一節用了兩個「救贖」的字。****前一個，是付出代價把人贖回來；後一個，是以親屬的身份，把人贖回來。****神是用代價、用親屬的身份，贖回雅各。**','**{H1669}**（da’avah，衰弱憂愁）：「**他們也不再有一點愁煩**」。**這個字，形容一個人因憂傷而枯乾衰弱。****神要他們的心，像澆灌的園子。**'],
exp=['十節說：**趕散以色列的，必招聚他，又看守他，好像牧人看守羊群。****這個比喻，把一位審判者，變成一位牧人。****趕散他們的是神，招聚他們的也是神。****神不是把他們丟下，而是在遠處等候。**','十一節的**救贖**，是一個強而有力的動詞：**救贖他脫離比他更強之人的手。****以色列沒有力量自己回來；神是那位更強的人。**','十二節的圖畫，是一個**豐盛的聚會**：**五穀、新酒、油、羊羔、牛犢。****他們的心必像澆灌的園子。****從枯乾的心，到被澆灌的園子，是這一章最美的轉變。**']),
dict(a=13,z=14,star=2,lit=L(13,14),
key=[('跳舞','H4234','bamakhol','舞蹈'),('悲哀','H60','evlam','哀傷'),('歡喜','H8342','lesason','喜樂'),('安慰','H5162','venikhamtim','安慰'),('滿足','H7301','veravethi','使飽足'),('恩惠','H2898','tuvi','美善、恩惠'),('愁煩','H3015','miyagonam','憂愁')],
gram=['**{H5162}**（nakham，安慰）：這個字，與三十一章19節的「**懊悔**」，以及十五節的「**受安慰**」，是同一個字根。**同一個字，在一章之內，有不同的面貌：安慰、懊悔、受安慰。**','**{H7301}**（ravah，飽足）：「**我必以肥油使祭司的心滿足**」。**這個字，常用來描寫喝飽了水的田地。****神要使人的心，被澆得飽足。**'],
exp=['十三節說：**我要使他們的悲哀變為歡喜。****神的安慰，是一個「變」字：悲哀變歡喜，愁煩轉快樂。****神不是叫悲哀消失，而是把悲哀轉成別的東西。**','請留意，**處女、年少的、年老的，一同歡樂。****不同年紀的人，在同一個舞蹈裡。****這是一個老少一起的盼望。**','十四節說：**我必以肥油使祭司的心滿足。****祭司在被擄的日子裡，大概是最失落的一群：沒有殿，沒有祭。****神說，我要使你們的心，滿足。**']),
dict(a=15,z=15,star=3,lit=L(15,15),
key=[('拉瑪','H7414','berama','（地名）高處'),('號咷痛哭','H5092','nehi','哀號'),('拉結','H7354','rakhel','（人名）母羊'),('不肯','H3985','meana','拒絕'),('安慰','H5162','lehinakhem','得安慰'),('不在了','H369','enennu','沒有了')],
gram=['**{H5092}**（nehi，哀號）：「**號咷痛哭**」。**這一節用了三個詞，形容哭聲：哀號、哭泣、苦痛。****這是一個母親，哭到無法安慰的聲音。**','**{H3985}**（ma’an，拒絕）：「**不肯受安慰**」。**神沒有責備拉結不肯受安慰。****神把她的哭聲，寫進聖經。**'],
exp=['這一節，是整章的轉折。**前面是安慰、歌唱、跳舞；突然，一個母親的哭聲。****拉結，是雅各心愛的妻子，是約瑟與便雅憫的母親。****她的墳墓，經上記在便雅憫境內（撒上十2）。**她被想像成一位母親，在被擄之民經過的路上，**為她不在了的兒女，哭泣。**','請留意：**神沒有叫拉結止住哭泣。****神沒有說「不要哭」。****神把這一節，放在安慰之書的中間。****這說明：真正的安慰，不是繞過悲傷，而是穿過悲傷。**','**馬太福音二章17--18節，引用了這一節，用來描寫伯利恆嬰孩被殺的悲痛。****這是新約自己作出的連結。**請與**十六、十七節一起讀**：**哭聲不是結局，後面有賞賜，有指望，有歸回。**']),
dict(a=16,z=17,star=3,lit=L(16,17),
key=[('禁止','H4513','mini','攔阻'),('流淚','H1832','midimah','眼淚'),('賞賜','H7939','sakhar','報酬、賞賜'),('敵國','H341','oyev','仇敵'),('指望','H8615','tiqvah','指望'),('末後','H319','akharit','末後、結局'),('境界','H1366','gvulam','境界')],
gram=['**{H7939}**（sakhar，賞賜）：「**因你所做之工必有賞賜**」。**拉結的「工」，是什麼？她養育兒女，為他們流淚。****神看見這一切，說：必有賞賜。**','**{H8615}**（tiqvah，指望）：**二十九章11節「末後有指望」，與這裡「你末後必有指望」，是同一個字。****指望，是一條繩子，神把這條繩子，遞給哭泣的母親。**'],
exp=['十六節，神對拉結說：**你禁止聲音不要哀哭，禁止眼目不要流淚。****這句話，不是叫她別哭，而是說：你的哭聲，神聽見了；你可以安息了。****因為你所做之工必有賞賜。**','**神的答案，是三個應許：賞賜（十六節）；兒女從敵國歸回（十六節）；末後有指望（十七節）。****請留意：神沒有說，你的兒女「沒有死」；祂說，他們必歸回。****這個應許，對被擄之民是歸回；對一切在悲傷中的人，是盼望。**','請對照**二十九章11節**：**「要叫你們末後有指望」。****同一個字「指望」，在二十九章，是對被擄之民的；在這裡，是對一位哭泣的母親的。****神的指望，一直追到最深的悲傷裡。**']),
dict(a=18,z=20,star=3,lit=L(18,20),
key=[('責罰','H3256','yisartani','管教、責罰'),('牛犢','H5695','keegel','小牛'),('回轉','H7725','hashiveni','使我回轉'),('懊悔','H5162','nikhamti','後悔、懊悔'),('愛子','H3357','yaqir','寶貴的'),('心腸','H4578','meai','腸、內心'),('憐憫','H7355','arakhamenu','憐憫')],
gram=['**{H3357}**（yaqir，寶貴）：「**以法蓮是我的愛子嗎？**」直譯是「**以法蓮是我寶貴的兒子嗎？**」**這是一個反問，答案是：是的。****神用問句，說出祂對以法蓮的愛。**','**{H4578}**（me’ayim，腸）：「**我的心腸戀慕他**」。**這個字，原文是「腸」，古人以腸子為情感的所在。****神的愛，不是一個決定，而是一種內臟的翻騰。**','**{H7355}**（racham，憐憫）：**這個字，與「子宮」同一個字根。****「我必要憐憫他」，是母親式的憐憫。**'],
exp=['十八、十九節，是**以法蓮的悔改禱告**，也是**聖經中最誠實的悔改禱告之一**：**像不慣負軛的牛犢**：他承認自己的倔強；**「求你使我回轉，我便回轉」**：他承認，**連回轉的力量，也要神給**。','請留意：**他的悔改，不是因為害怕；而是「我回轉以後就真正懊悔；受教以後就拍腿歎息」。****先回轉，後懊悔；先被神拉回，才看見自己的羞恥。**這與一般人的次序，正好相反。','二十節，**神回答：以法蓮是我的愛子嗎？****神的回答，不是一個條款，而是一個問句，充滿感情。****「我每逢責備他，仍深顧念他。」****神的責備，是愛的一種形式。****祂的心腸戀慕，祂必要憐憫。**']),
dict(a=21,z=22,star=2,lit=L(21,22),
key=[('指路碑','H6725','tsiyunim','路標'),('引路柱','H8564','tamrurim','路標柱'),('大路','H4546','lamsilah','大道'),('回轉','H7725','shuvi','回轉'),('背道的民','H7728','habat hashovevah','背道的女兒'),('新事','H2319','khadashah','新的事'),('護衛','H5437','tesovev','環繞、護衛')],
gram=['**{H6725}**（tsiyun，路標）：「**為自己設立指路碑**」。**被擄的人，要在回家的路上，立下記號，讓自己不會迷路。****神要他們，記住回家的路。**','**{H7728}**（shovevah，背道的）：**這個字與「回轉」（shuv）同一個字根，形成一個雙關：「背道的民哪（shovevah），回轉吧（shuvi）。」****同一個字根，一個是離開，一個是回來。**'],
exp=['二十一節，**神吩咐被擄的人，豎立路標：你要留心向大路，就是你所去的原路。****你被擄去的時候，走的是哪一條路，回來的時候，也走哪一條路。****記住路，是回家的一部分。**','二十二節，**神說：背道的民哪，你反來覆去要到幾時呢？****神的口氣，是一位父親，對一個搖擺的孩子。****接著說：耶和華在地上造了一件新事。****這個「新事」，與三十一至三十四節的「新約」，用的是同一個字（khadash）。**','「**女子護衛男子**」這一句，是整卷書最難解的句子之一，歷來有許多不同的讀法。**本講義不下定論**，只確定一件事：**這是神造的新事，不是人的計畫。**']),
dict(a=23,z=26,star=2,lit=L(23,26),
key=[('公義','H6664','tsedeq','公義'),('聖山','H6944','harhaqodesh','聖山'),('賜福','H1288','yvarekhekha','祝福'),('疲乏','H5889','ayefah','疲乏的'),('愁煩','H1669','davah','憂愁的'),('醒了','H6974','hiqitsoti','醒來'),('香甜','H6149','arevah','甘甜')],
gram=['**{H6664}**（tsedeq，公義）：「**公義的居所**」。**這個稱呼，意思是：耶路撒冷，將成為公義居住的地方。****不是完美的人住在那裡，而是公義的神住在那裡。**','**{H6974}**（qits，醒來）：「**我醒了，覺著睡得香甜**」。**這是先知的話：讀法很多。****多數解經者，把它讀作耶利米在領受這一連串安慰之後的反應；本講義不下定論。**'],
exp=['二十三、二十四節，**是歸回之後的畫面：猶大地與城邑，再次聽見祝福的話：願耶和華賜福給你。****農夫、牧人，一同住在其中。****一個重新有人耕種、有人牧放的地方。**','二十五節是**一個很溫柔的應許**：**疲乏的人，我使他飽飫；愁煩的人，我使他知足。****神所醫治的，不只是大事，也包括人的疲乏和愁煩。****疲乏的人，有時比受傷的人更多。**','二十六節，**先知說：「我醒了，覺著睡得香甜！」****這一句，為這一段安慰，加上了一個謙卑的註腳：連先知，也像在夢中一樣。****神的安慰，好得讓人不敢相信。**']),
dict(a=27,z=30,star=3,lit=L(27,30),
key=[('播種','H2232','vezaarti','播種'),('拔出','H5428','lintosh','拔出'),('拆毀','H5422','ulintots','拆毀'),('建立','H1129','livnot','建造'),('栽植','H5193','ulintoa','栽種'),('酸葡萄','H1155','boser','酸的、未熟的葡萄'),('死亡','H4191','yamut','死')],
gram=['**{H5428}**（nathash，拔出）、**{H5422}**（nathats，拆毀）：**這兩個動詞，與一章10節耶利米的使命，完全相同：拔出、拆毀、毀壞、傾覆、建立、栽植。****耶利米書的第一章，在這裡，終於走到了「建立、栽植」。**','**{H1155}**（boser，未熟的葡萄）：「**父親吃了酸葡萄，兒子的牙酸倒了**」。**這是一句當時流行的諺語，也見於以西結書十八章2節。****這句話，被人用來抱怨：我們受苦，是因為上一代的罪。**'],
exp=['二十八節是整卷書的**一個回頭**：**我先前怎樣留意將他們拔出、拆毀、毀壞、傾覆、苦害，也必照樣留意將他們建立、栽植。****神用同一種殷勤（「留意」，原文shaqad，意思是警醒看守）去建立。****神不是只會毀壞，祂對建立，同樣認真。**','二十九、三十節，**說到一句諺語：「父親吃了酸葡萄，兒子的牙酸倒了。」****這句諺語，有真實的一面：上一代的罪，確實影響下一代；也有被濫用的一面：把責任，全推給上一代。****神說：各人必因自己的罪死亡。****這不是否認家族的影響，而是說：每一個人，都要對神負責。**','請留意**這兩個應許的搭配**：**二十七、二十八節，是「我要建立」；二十九、三十節，是「你要負責」。****神的恢復，既不讓人推卸責任，也不讓人被上一代永遠捆綁。**']),
dict(a=31,z=34,star=3,lit=L(31,34),
key=[('新約','H1285','brit khadashah','新的約'),('背了','H6565','hefeiru','破壞、違背'),('丈夫','H1166','baalti','作丈夫、主人'),('律法','H8451','torati','我的律法、教導'),('寫在','H3789','ektavenah','寫'),('認識','H3045','yadu','認識'),('赦免','H5545','eslakh','赦免')],
gram=['**{H3789}**（katav，寫）：「**寫在他們心上**」。**第一個約，是寫在石版上（出三十四1）；新約，是寫在心上。****寫的地方，從外面，變成裡面。**','**{H5545}**（salakh，赦免）：**這個動詞，在聖經中，**只以神為主詞**。**只有神，可以這樣赦免。**「**不再記念他們的罪惡**」，不是神的忘記，而是神的決定：**不再拿這些罪，來對付他們。**','**{H3045}**（yada，認識）：**這個字，不是知道一些資料，而是親密的認識。****「你該認識耶和華」，是邀請人進入一種關係。**'],
exp=['三十一節，**「新約」這個詞，在舊約裡，只出現在這一處。****神說，這個約，不像出埃及時所立的約。****請留意三十二節的措辭：我雖作他們的丈夫，他們卻背了我的約。****舊約的問題，不在神，在人。**','**新約有四個特色**：**第一，律法寫在心上（三十三節）；第二，彼此是神的子民（三十三節）；第三，人人都認識耶和華（三十四節）；第四，罪被赦免，不再被記念（三十四節）。****前三個，是關係的改變；最後一個，是基礎。****沒有赦免，沒有新約。**','**新約自己多次回顧這一段**：**路加福音二十二章20節（耶穌設立聖餐）、哥林多後書三章6節、希伯來書八章8--12節、十章15--17節。****本講義，只跟新約自己作過的連結，其餘不下定論。****我們不用這一段，去論斷任何民族，也不用它排任何時間表。**','**三十四節最後一句：「我要赦免他們的罪孽，不再記念他們的罪惡。」****這是整個新約的根基。****所有關於「新約」的爭論，若讓人忘記了這一句，就走偏了。**']),
dict(a=35,z=37,star=2,lit=L(35,37),
key=[('太陽','H8121','shemesh','太陽'),('定例','H2708','khuqot','定例、規定'),('波浪','H1530','galav','波浪'),('萬軍','H6635','tsvaot','萬軍'),('廢掉','H4185','yamushu','離去、廢掉'),('量度','H4058','yimadu','量度'),('棄絕','H3988','emas','拒絕、棄絕')],
gram=['**{H2708}**（khuqqah，定例）：**日、月、星，各有定例。****神用天體的秩序，來擔保祂與以色列的約。**','**{H3988}**（ma’as，棄絕）：「**我就因以色列後裔一切所行的棄絕他們**」。**神說：除非人能量度上天、尋察下地的根基，否則，我不會棄絕。****這是用「不可能」，說出神的信實。**'],
exp=['三十五節，**神是創造者：使太陽白日發光，使星月有定例，攪動大海。****神介紹自己，用的是創造的大能。****因為接下來的應許，需要一位創造者，來擔保。**','三十六、三十七節，**兩個「若」：若日月的定例能廢掉，以色列就斷絕；若能量度上天、尋察下地的根基，神就棄絕他們。****這兩個「若」，都是不可能的事。****神用不可能的事，說出祂對祂的百姓的承諾是可能的。**','這與**三十三章20--26節**，是遙相呼應的。**神的應許，不是放在人的忠心上，而是放在祂自己的名上。****「萬軍之耶和華是他的名」。**']),
dict(a=38,z=40,star=2,lit=L(38,40),
key=[('建造','H1129','nivnetah','被建造'),('哈楠業','H2606','khananel','（地名）神施恩'),('角門','H6438','pinah','角、隅'),('準繩','H6957','qav','準繩、測量線'),('為聖','H6944','qodesh','聖潔'),('傾覆','H2040','yehares','拆毀、傾覆')],
gram=['**{H6944}**（qodesh，聖）：「**都要歸耶和華為聖**」。**連「拋屍的全谷和倒灰之處」這些最不潔的地方，也要歸神為聖。****重建的範圍，包括最不潔的地方。**','**{H6957}**（qav，準繩）：**一條測量線。****神在量度這座城，不是用人的規劃，而是用祂自己的準繩。**'],
exp=['最後三節，**是一幅城的地圖**：**從哈楠業樓，到角門，到迦立山，到歌亞，到汲淪溪，到馬門。****這些地名，有的今天已不能確定位置。****神用具體的地名，說明這個應許，是真實的，不是神話。**','請留意**四十節的重點：「拋屍的全谷和倒灰之處」。****那是這座城，最不潔、最令人想忘記的地方。****可是神說，連這些地方，也要歸耶和華為聖。****神的重建，沒有一個死角。**','**最後一句：「不再拔出，不再傾覆，直到永遠。」****這句話，回應了一章10節耶利米的使命，也回應了二十八節。****一卷書，從「拔出、拆毀」，走到「不再拔出，不再傾覆」。**']),
]
